import sys
import pandas as pd
import numpy as np
import json

# Read CSV
df = pd.read_csv(sys.argv[1])

facts = []

# Helper function to convert numpy types to Python types
def to_python(val):
    if pd.isna(val):
        return None
    if isinstance(val, (np.integer, np.floating)):
        return float(val)
    return val

# 1. Top 3 entities by Revenue_TW
top_revenue = df.nlargest(3, 'Revenue_TW')
for idx, row in top_revenue.iterrows():
    if pd.notna(row['Revenue_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "TW",
            "value": round(to_python(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

# 2. Top 3 entities by Units_TW
top_units = df.nlargest(3, 'Units_TW')
for idx, row in top_units.iterrows():
    if pd.notna(row['Units_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "units",
            "period": "TW",
            "value": to_python(row['Units_TW']),
            "formula": "Units_TW"
        })

# 3. Top 3 entities by Orders_TW
top_orders = df.nlargest(3, 'Orders_TW')
for idx, row in top_orders.iterrows():
    if pd.notna(row['Orders_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "orders",
            "period": "TW",
            "value": to_python(row['Orders_TW']),
            "formula": "Orders_TW"
        })

# 4. Biggest WoW gainers (top 2)
wow_gainers = df[df['WoW_Pct'].notna()].nlargest(2, 'WoW_Pct')
for idx, row in wow_gainers.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "revenue",
        "period": "WoW",
        "value": round(to_python(row['WoW_Pct']), 1),
        "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
    })

# 5. Biggest WoW losers (top 2)
wow_losers = df[df['WoW_Pct'].notna()].nsmallest(2, 'WoW_Pct')
for idx, row in wow_losers.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "revenue",
        "period": "WoW",
        "value": round(to_python(row['WoW_Pct']), 1),
        "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
    })

# 6. Biggest YoY gainers (top 2)
yoy_gainers = df[df['YoY_Pct'].notna()].nlargest(2, 'YoY_Pct')
for idx, row in yoy_gainers.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "revenue",
        "period": "YoY",
        "value": round(to_python(row['YoY_Pct']), 1),
        "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
    })

# 7. Biggest YoY losers (top 2)
yoy_losers = df[df['YoY_Pct'].notna()].nsmallest(2, 'YoY_Pct')
for idx, row in yoy_losers.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "revenue",
        "period": "YoY",
        "value": round(to_python(row['YoY_Pct']), 1),
        "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
    })

# 8. Top 3 by Share_Pct
top_share = df[df['Share_Pct'].notna()].nlargest(3, 'Share_Pct')
for idx, row in top_share.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "share",
        "period": "TW",
        "value": round(to_python(row['Share_Pct']), 1),
        "formula": "Revenue_TW / sum(Revenue_TW) * 100"
    })

# 9. TOTAL Revenue_TW
total_revenue_tw = df['Revenue_TW'].sum()
if pd.notna(total_revenue_tw):
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "TW",
        "value": round(to_python(total_revenue_tw), 2),
        "formula": "sum(Revenue_TW)"
    })

# 10. TOTAL Revenue_LW
total_revenue_lw = df['Revenue_LW'].sum()
if pd.notna(total_revenue_lw):
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "LW",
        "value": round(to_python(total_revenue_lw), 2),
        "formula": "sum(Revenue_LW)"
    })

# 11. TOTAL WoW
if pd.notna(total_revenue_tw) and pd.notna(total_revenue_lw) and total_revenue_lw != 0:
    total_wow = (total_revenue_tw - total_revenue_lw) / total_revenue_lw * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "WoW",
        "value": round(to_python(total_wow), 1),
        "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
    })

# 12. TOTAL Units_TW
total_units_tw = df['Units_TW'].sum()
if pd.notna(total_units_tw):
    facts.append({
        "entity": "TOTAL",
        "metric": "units",
        "period": "TW",
        "value": to_python(total_units_tw),
        "formula": "sum(Units_TW)"
    })

# 13. TOTAL Orders_TW
total_orders_tw = df['Orders_TW'].sum()
if pd.notna(total_orders_tw):
    facts.append({
        "entity": "TOTAL",
        "metric": "orders",
        "period": "TW",
        "value": to_python(total_orders_tw),
        "formula": "sum(Orders_TW)"
    })

# Limit to 25 facts
facts = facts[:25]

print(json.dumps(facts))
